BEGIN TRANSACTION;
DROP TABLE IF EXISTS "city";
CREATE TABLE "city" (
	"id"	INTEGER,
	"name"	TEXT,
	"region"	TEXT,
	"sea_area"	TEXT,
	"culture"	TEXT,
	"언어"	TEXT,
	"설명"	TEXT,
	"지도 이미지 포인트(x)"	TEXT,
	"지도 이미지 포인트(y)"	TEXT,
	"도시좌표(x)"	TEXT,
	"도시좌표(y)"	TEXT,
	"분류"	TEXT,
	"입항허가"	TEXT,
	"입구"	TEXT,
	"시설"	TEXT,
	"플래그 퀘스트 고유번호"	TEXT,
	"투자 금액"	TEXT,
	"투자 보상"	TEXT,
	"거래 금액"	TEXT,
	"거래 보상"	TEXT,
	"낚시"	TEXT,
	PRIMARY KEY("id")
);
DROP TABLE IF EXISTS "consumable";
CREATE TABLE "consumable" (
	"id"	INTEGER NOT NULL,
	"type"	TEXT,
	"name"	TEXT,
	"additional_Name"	TEXT,
	"description"	TEXT,
	"category"	TEXT,
	"usage_Effect"	TEXT,
	"features"	TEXT,
	"Item"	TEXT,
	"Duplicate"	TEXT,
	PRIMARY KEY("id")
);
DROP TABLE IF EXISTS "d0";
CREATE TABLE "d0" (
	"id"	INTEGER,
	"item_name"	TEXT,
	"item_id"	INTEGER,
	"explanation"	TEXT
);
DROP TABLE IF EXISTS "dhoSQL";
CREATE TABLE "dhoSQL" (
	"info"	TEXT
);
DROP TABLE IF EXISTS "discovery";
CREATE TABLE "discovery" (
	"id"	INT AUTO_INCREMENT,
	"type"	VARCHAR(255),
	"name"	VARCHAR(255),
	"additional_name"	VARCHAR(255),
	"name_key"	VARCHAR(255),
	"description"	TEXT,
	"category"	VARCHAR(255),
	"difficulty"	INT,
	"card_points"	INT,
	"discovery_experience"	INT,
	"card_acquisition_experience"	INT,
	"report_reputation"	INT,
	"discovery_method"	VARCHAR(255),
	"discovery_location"	VARCHAR(255),
	"discovery_rank"	TEXT,
	"additional_description"	TEXT,
	"era"	VARCHAR(255),
	"time_period"	VARCHAR(255),
	"weather"	VARCHAR(255),
	"coordinates"	VARCHAR(255),
	PRIMARY KEY("id")
);
DROP TABLE IF EXISTS "dungeon";
CREATE TABLE "dungeon" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT,
	"additional_name"	TEXT,
	"explanation"	TEXT,
	"floor"	TEXT,
	"rank"	INTEGER,
	"exploration"	INTEGER,
	"boarding_pass"	INTEGER,
	"entrance"	TEXT,
	"preceding"	TEXT,
	"equipment"	TEXT,
	"etc"	TEXT,
	"discovery_boss_completed"	TEXT,
	"discovery_hidden_room_box"	TEXT,
	"regular_floor_box"	TEXT,
	"hidden_room_box"	TEXT,
	"boss_box"	TEXT,
	"boss_completed"	TEXT,
	PRIMARY KEY("id")
);
DROP TABLE IF EXISTS "field";
CREATE TABLE "field" (
	"id"	INTEGER NOT NULL,
	"name"	TEXT,
	"additional_name"	TEXT,
	"region"	TEXT,
	"field_type"	TEXT,
	"entrance"	TEXT,
	"entrance_id"	TEXT,
	"flag_quest"	TEXT,
	"flag_quest_id"	TEXT,
	"explanation"	TEXT,
	"mapx"	TEXT,
	"mapy"	TEXT,
	"coordinates_x"	TEXT,
	"coordinates_y"	TEXT,
	"classification"	TEXT,
	"permission_enter port"	TEXT,
	"field_resurvey_compensation"	TEXT,
	"field18"	TEXT,
	"field19"	TEXT,
	"field20"	TEXT,
	"field21"	TEXT,
	"field22"	TEXT,
	PRIMARY KEY("id")
);
DROP TABLE IF EXISTS "landnpc";
CREATE TABLE "landnpc" (
	"id"	INTEGER,
	"name"	TEXT,
	"lv"	TEXT,
	"feature"	TEXT,
	"additionalname"	TEXT,
	"description"	TEXT,
	"fieldname"	TEXT,
	"technique"	TEXT,
	"item_id"	TEXT,
	"field_id"	TEXT,
	"technic_id"	TEXT,
	"비고"	TEXT,
	PRIMARY KEY("id")
);
DROP TABLE IF EXISTS "npcsale";
CREATE TABLE "npcsale" (
	"id"	INTEGER,
	"npc"	TEXT,
	"city"	TEXT,
	"city_id"	INTEGER,
	"cultural"	TEXT,
	"group"	TEXT,
	"item_id"	INTEGER,
