DROP TABLE IF EXISTS "quest";
CREATE TABLE "quest" (
	"id"	INT AUTO_INCREMENT,
	"type"	VARCHAR(255),
	"name"	VARCHAR(255),
	"additional_name"	VARCHAR(255),
	"description"	TEXT,
	"series"	VARCHAR(255),
	"difficulty"	INT,
	"era"	VARCHAR(255),
	"category"	VARCHAR(255),
	"location"	VARCHAR(255),
	"destination"	VARCHAR(255),
	"destination_coordinates"	VARCHAR(255),
	"discovery"	VARCHAR(255),
	"preceding_discovery_quest"	VARCHAR(255),
