	"required_items"	VARCHAR(255),
	"guide"	TEXT,
	"progress"	VARCHAR(255),
	"previous_continuous_quest_id"	TEXT,
	"episode"	INT,
	"one_time_only"	INT,
	"rare"	INT,
	"association_required"	INT,
	"skills"	VARCHAR(255),
