	"other"	TEXT,
	"reward_money"	INT,
	"advance_payment"	INT,
	"report_experience"	VARCHAR(255),
	"report_reputation"	VARCHAR(255),
	"reward_items"	VARCHAR(255),
	"reward_immigrants"	VARCHAR(255),
	"reward_techniques"	VARCHAR(255),
	"reward_title"	VARCHAR(255),
