DROP TABLE IF EXISTS "recipe";
CREATE TABLE "recipe" (
	"id"	INTEGER,
	"name"	TEXT,
	"description"	TEXT,
	"recipe_book_id"	INTEGER,
	"required_Skill"	TEXT,
	"ingredients"	TEXT,
	"sophia"	INTEGER,
	"era"	TEXT,
	"home_production"	TEXT,
	"development"	TEXT,
