	"own_Industrial_city"	TEXT,
	"title"	TEXT,
	"consumption_contribution"	INTEGER,
	"other"	TEXT,
	"success"	TEXT,
	"greatsuccess"	TEXT,
	"failure"	TEXT,
	PRIMARY KEY("id")
);
DROP TABLE IF EXISTS "recipebook";
CREATE TABLE "recipebook" (
	"id"	INTEGER,
	"sveries"	TEXT,
	"name"	TEXT,
	"additionalname"	TEXT,
	"description"	TEXT,
	"productionNPC"	TEXT,
	"era"	TEXT,
