 (3293435,'술탄 위임장의 재현법','그란데 가나돌의 비보
술탄의 위임장을
재현하는 방법.',2997984,'[{"ref": 2297, "name": "공예", "value": 15}]','[{"ref": 5516, "name": "소녀전사의 부적", "value": 16}, {"ref": 3292948, "name": "환해의 항해 일지", "value": 20}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'하이레딘(그란데 가나돌) 처치 후 1회 한정생산','[{"ref": 3294658, "name": "술탄 위임장", "value": 1}]',NULL,NULL),
 (3293437,'커먼 센스의 출판법','그란데 가나돌의 비보
커먼 센스를 출판하는 방법.',2997984,'[{"ref": 2297, "name": "공예", "value": 15}]','[{"ref": 6243, "name": "수정눈", "value": 12}, {"ref": 3292948, "name": "환해의 항해 일지", "value": 20}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'조지 워싱턴(그란데 가나돌) 처치 후 1회 한정생산','[{"ref": 3293700, "name": "커먼 센스", "value": 1}]',NULL,NULL),
 (3352556,'소재에 대한 고집','형태에만 집착하다 보니
소재에 대한 의식이 부족했다.
좋은 재질의 목재를 사용해 보자.',2964160,'[{"ref": 2297, "name": "공예", "value": 12}]','[{"ref": 2570, "name": "면 원단", "value": 10}, {"ref": 5452, "name": "명인 목수의 목공도구", "value": 5}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 3, 소피아 : 140',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964249, "name": "발보스 레그 체어", "value": 1}]',NULL,NULL),
 (3352558,'소재에 대한 고집 2','가늘면서도 부러지지 않는
목재를 손에 넣었다. 이걸 사용하면 미와
강도를 모두 갖출 수 있을 지도 모른다.',2964160,'[{"ref": 2297, "name": "공예", "value": 12}]','[{"ref": 2570, "name": "면 원단", "value": 12}, {"ref": 5452, "name": "명인 목수의 목공도구", "value": 8}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 3, 소피아 : 145',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964251, "name": "caquetoire", "value": 1}]',NULL,NULL),
 (3352560,'앉았을 때의 편안함을 추구','앉는 면이 딱딱하고 등받이가 불편하다고
친구가 조언했다. 오래 앉아도
쾌적하게 앉을 수 있는 의자를 만들자.',2964160,'[{"ref": 2297, "name": "공예", "value": 13}]','[{"ref": 2570, "name": "면 원단", "value": 14}, {"ref": 5452, "name": "명인 목수의 목공도구", "value": 11}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 3, 소피아 : 150',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964253, "name": "카브리올 레그", "value": 1}]',NULL,NULL),
 (3352563,'격식이라는 시점','의자는 놓이는 장소도
의식해야만 한다.
격식이 높은 의자를 만들어 보자.',2964160,'[{"ref": 2297, "name": "공예", "value": 13}]','[{"ref": 2570, "name": "면 원단", "value": 16}, {"ref": 5452, "name": "명인 목수의 목공도구", "value": 14}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 4, 소피아 : 155',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964255, "name": "테이퍼드 레그", "value": 1}]',NULL,NULL),
 (3352567,'소중한 사람에게 선물하는 의자','소중한 사람이 앉은 모습을 상상해
의자를 만들어 보자. 분명
멋진 의자가 만들어질 것이다.',2964160,'[{"ref": 2297, "name": "공예", "value": 14}]','[{"ref": 2570, "name": "면 원단", "value": 18}, {"ref": 5452, "name": "명인 목수의 목공도구", "value": 17}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 4, 소피아 : 160',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964257, "name": "다이닝 체어", "value": 1}]',NULL,NULL),
 (3352573,'옥좌로 향하는 계단','충분한 기술，지식，경험. 지금의
내게 옥좌를 만들 자격이
있을까? 일단 시험삼아 만들어 보자.',2964160,'[{"ref": 2297, "name": "공예", "value": 15}]','[{"ref": 2697, "name": "은세공", "value": 10}, {"ref": 5807, "name": "고급벨벳", "value": 10}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 4, 소피아 : 170',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964261, "name": "벨벳 체어", "value": 1}]',NULL,NULL),
 (3352577,'보인 정상','긴 수련의 끝이 보였다.
남은 건 ''각오''뿐. 왕에게 걸맞은
의자를，마지막 시제품을.',2964160,'[{"ref": 2297, "name": "공예", "value": 15}]','[{"ref": 2691, "name": "금세공", "value": 10}, {"ref": 5807, "name": "고급벨벳", "value": 15}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 4, 소피아 : 175',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964263, "name": "데커레이티브 체어", "value": 1}]',NULL,NULL),
 (3352579,'장인의 솜씨','동경했던 옥좌라는 의자.
지금의 나라면 그곳에 도달할 수 있다.
자，궁극의 의자를 만들자.',2964160,'[{"ref": 2297, "name": "공예", "value": 16}]','[{"ref": 6152, "name": "명인 목수의 수복 도구", "value": 3}, {"ref": 5808, "name": "최고급벨벳", "value": 20}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 4, 소피아 : 180',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964265, "name": "왕가의 의자", "value": 1}]',NULL,NULL),
 (3352583,'기술의 멋','어엿한 장인으로서의 자부심.
기술의 멋을 모은 지금의 ''최고''
한번 만들어 보자.',2964160,'[{"ref": 2297, "name": "공예", "value": 14}]','[{"ref": 2570, "name": "면 원단", "value": 20}, {"ref": 5452, "name": "명인 목수의 목공도구", "value": 20}, {"ref": 8635, "name": "목재 가공", "value": 1}]','랭크 : 4, 소피아 : 165',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'의자 장인',NULL,NULL,'[{"ref": 2964259, "name": "살롱 체어", "value": 1}]',NULL,NULL),
 (3376125,'노른자의 활용법','둥근 파이 반죽의 둥글게 자른
부분을 컵 모양으로 만들어
크림을 붓고 오븐에서 굽는다.',3376043,'[{"ref": 2316, "name": "조리", "value": 10}]','[{"ref": 2816, "name": "달걀", "value": 5}, {"ref": 2867, "name": "파이 반죽", "value": 3}, {"ref": 2781, "name": "설탕", "value": 1}]','랭크 : 2, 소피아 : 50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376085, "name": "파스탈 데 나타", "value": 0}]',NULL,NULL),
 (3376131,'마늘 냄새가 나는 접시 요리','올리브유에 썬 마늘과
재료를 넣어 약불로 끓인다.
빵과 함께 먹어도 맛있다.',3376043,'[{"ref": 2316, "name": "조리", "value": 10}]','[{"ref": 2785, "name": "올리브유", "value": 5}, {"ref": 2661, "name": "마늘", "value": 1}, {"ref": 2837, "name": "새우", "value": 2}]','랭크 : 2, 소피아 : 40',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376092, "name": "아히요", "value": 5}]',NULL,NULL),
 (3376135,'신대륙에서 전해 내려오는 건강 음료','카카우아틀을 설탕과 아니스로
단맛을 낸다. 좋은 약이라고 해도
가급적 즐겁게 마시고 싶다.',3376043,'[{"ref": 2316, "name": "조리", "value": 10}]','[{"ref": 2781, "name": "설탕", "value": 1}, {"ref": 2649, "name": "아니스", "value": 1}, {"ref": 5685, "name": "카카우아틀", "value": 5}]','랭크 : 2, 소피아 : 60',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376259, "name": "핫초코", "value": 0}]',NULL,NULL),
 (3376143,'둥글게 굽고 사각형으로 접기','메밀가루로 만든 반죽을 둥글게 굽는다.
표면이 마르면 재료를 올려
네 방향 모두 접는다.',3376043,'[{"ref": 2316, "name": "조리", "value": 10}]','[{"ref": 2544, "name": "치즈", "value": 1}, {"ref": 2816, "name": "달걀", "value": 5}, {"ref": 3040, "name": "소바", "value": 5}]','랭크 : 2, 소피아 : 50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376267, "name": "갈레트 브루통", "value": 0}]',NULL,NULL),
 (3376151,'이것이야말로 본격파의 제조법','여러 종류의 생선을 향신료와 함께
큰 냄비에 넣고 끓인다. 생선은
꺼내고 다른 접시에 담아 대접한다.',3376043,'[{"ref": 2316, "name": "조리", "value": 10}, {"ref": 2309, "name": "사교", "value": 2}]','[{"ref": 2880, "name": "닭고기", "value": 2}, {"ref": 2838, "name": "성대", "value": 2}, {"ref": 5609, "name": "부야베스", "value": 1}]','랭크 : 2, 소피아 : 480',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376283, "name": "정통 부야베스", "value": 0}]',NULL,NULL),
 (3376159,'별을 바라보는 파이','물고기와 감자를 파이 반죽으로 감싸
굽는다. 생선 머리가 반죽에서
튀어나올 것처럼 장식한다.',3376115,'[{"ref": 2316, "name": "조리", "value": 10}, {"ref": 2284, "name": "인식", "value": 1}]','[{"ref": 2797, "name": "감자", "value": 5}, {"ref": 2867, "name": "파이 반죽", "value": 5}, {"ref": 2863, "name": "청어", "value": 10}]','랭크 : 2, 소피아 : 40',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376287, "name": "스타게이지 파이", "value": 0}]',NULL,NULL),
 (3376163,'단식 전에 먹는 팬케이크','팬케이크를 얇게 구워
둥글게 만다. 먹을 때는 취향에
따라 레몬즙을 곁들이면 좋다.',3376115,'[{"ref": 2316, "name": "조리", "value": 10}]','[{"ref": 2807, "name": "나무 열매", "value": 1}, {"ref": 2545, "name": "밀가루", "value": 5}, {"ref": 2781, "name": "설탕", "value": 1}]','랭크 : 2, 소피아 : 50',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376312, "name": "브리티시 팬케이크", "value": 0}]',NULL,NULL),
 (3376167,'티 타임에 곁들이는 메뉴','갓 짠 우유를 저온에
충분히 가열시킨 후 차갑게 식혀
클로티드 크림을 만든다.',3376115,'[{"ref": 2316, "name": "조리", "value": 10}]','[{"ref": 2850, "name": "우유", "value": 2}, {"ref": 6001, "name": "잼 스콘", "value": 5}]','랭크 : 2, 소피아 : 40',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376317, "name": "크림을 얹은 스콘", "value": 0}]',NULL,NULL),
 (3376171,'구성이 풍부한 아침 식사','풍부한 구성의 메뉴를
하나의 접시에 담았다.
브렉퍼스트 티도 꼭 곁들이자.',3376115,'[{"ref": 2316, "name": "조리", "value": 10}]','[{"ref": 2830, "name": "베이컨", "value": 5}, {"ref": 2638, "name": "홍차", "value": 5}, {"ref": 5599, "name": "머핀", "value": 5}]','랭크 : 2, 소피아 : 40',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[{"ref": 3376319, "name": "풀 브렉퍼스트", "value": 0}]',NULL,NULL),
